select *, max(amount) over (partition by txn_type order by cast(txn_time as bigint) range between 7776000 preceding and current row) as amount_max_90d, sum(amount) over (partition by merchant order by amount, id rows between unbounded preceding and current row) as running_amount, avg(amount) over (partition by txn_type order by txn_time, id rows between 2 preceding and 1 preceding) as amount_avg_2_prior, max(amount) over (partition by date_trunc('WEEK', txn_time) order by cast(txn_time as bigint) range between 604800 preceding and current row) as amount_max_7d from transactions where txn_type in ('CREDIT', 'REFUND')
